import 'dart:io';import 'dart:ui' as ui;import 'package:flutter/material.dart';import 'package:flutter/rendering.dart';import 'package:path_provider/path_provider.dart';import 'package:share_plus/share_plus.dart';import '../../../core/models/reading.dart';import '../../../core/models/zodiac_sign.dart';import '../../../core/theme/app_theme.dart';
class ShareCardScreen extends StatefulWidget{const ShareCardScreen({super.key,required this.reading,required this.sign});final HoroscopeReading reading;final ZodiacSign sign;@override State<ShareCardScreen> createState()=>_ShareCardScreenState();}
class _ShareCardScreenState extends State<ShareCardScreen>{final key=GlobalKey();bool busy=false;
Future<void> _share()async{setState(()=>busy=true);try{final boundary=key.currentContext!.findRenderObject() as RenderRepaintBoundary;final image=await boundary.toImage(pixelRatio:3);final data=await image.toByteData(format:ui.ImageByteFormat.png);if(data==null)throw StateError('Unable to render share card.');final dir=await getTemporaryDirectory();final file=File(dir.path+'/astrodaily-share.png');await file.writeAsBytes(data.buffer.asUint8List(),flush:true);await SharePlus.instance.share(ShareParams(files:[XFile(file.path)],text:'Astrology is for entertainment and self-reflection, not factual prediction or professional advice.'));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not create share card: '+e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Share card')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Preview your reading card before sharing.',style:TextStyle(color:AppTheme.muted)),const SizedBox(height:18),RepaintBoundary(key:key,child:Container(padding:const EdgeInsets.all(26),decoration:BoxDecoration(color:AppTheme.secondary,borderRadius:BorderRadius.circular(24),border:Border.all(color:AppTheme.line)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('A S T R O D A I L Y',style:TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w800,letterSpacing:2)),const SizedBox(height:26),Center(child:Text(sign.glyph,style:const TextStyle(fontSize:58,color:AppTheme.primary))),Center(child:Text(sign.name.toUpperCase(),style:const TextStyle(letterSpacing:2,fontWeight:FontWeight.w800))),const SizedBox(height:18),Text(reading.title,style:const TextStyle(fontSize:25,fontWeight:FontWeight.w700,color:AppTheme.ink)),const SizedBox(height:12),Text(reading.body,style:const TextStyle(fontSize:16,height:1.6,color:AppTheme.ink)),const SizedBox(height:22),Text(reading.periodStart,style:const TextStyle(color:AppTheme.muted)),const Divider(height:26),const Text('For entertainment and self-reflection only. Not factual prediction or professional advice.',style:TextStyle(fontSize:10,color:AppTheme.muted))]))),const SizedBox(height:18),FilledButton.icon(onPressed:busy?null:_share,icon:const Icon(Icons.share),label:Text(busy?'Preparing…':'Share image'))]));}
